-- READ-ONLY six-archive cohort summary; SELECT only.
SELECT 'gw1000' AS archive,5 AS gap_count,COUNT(DISTINCT gap_id) AS gaps_with_rows,5-COUNT(DISTINCT gap_id) AS gaps_without_rows,COUNT(*) AS source_rows,COUNT(DISTINCT CASE WHEN `outTemp` IS NOT NULL THEN gap_id END) AS gaps_with_outTemp, SUM(`outTemp` IS NOT NULL) AS values_outTemp, COUNT(DISTINCT CASE WHEN `outHumidity` IS NOT NULL THEN gap_id END) AS gaps_with_outHumidity, SUM(`outHumidity` IS NOT NULL) AS values_outHumidity, COUNT(DISTINCT CASE WHEN `rain` IS NOT NULL THEN gap_id END) AS gaps_with_rain, SUM(`rain` IS NOT NULL) AS values_rain, COUNT(DISTINCT CASE WHEN `rainRate` IS NOT NULL THEN gap_id END) AS gaps_with_rainRate, SUM(`rainRate` IS NOT NULL) AS values_rainRate, COUNT(DISTINCT CASE WHEN `windSpeed` IS NOT NULL THEN gap_id END) AS gaps_with_windSpeed, SUM(`windSpeed` IS NOT NULL) AS values_windSpeed, COUNT(DISTINCT CASE WHEN `windGust` IS NOT NULL THEN gap_id END) AS gaps_with_windGust, SUM(`windGust` IS NOT NULL) AS values_windGust, COUNT(DISTINCT CASE WHEN `barometer` IS NOT NULL THEN gap_id END) AS gaps_with_barometer, SUM(`barometer` IS NOT NULL) AS values_barometer FROM (SELECT CASE WHEN `dateTime`>1648403400 AND `dateTime`<1648475700 THEN 1 WHEN `dateTime`>1655394000 AND `dateTime`<1655397900 THEN 2 WHEN `dateTime`>1655568900 AND `dateTime`<1655572800 THEN 3 WHEN `dateTime`>1656935100 AND `dateTime`<1656942900 THEN 4 WHEN `dateTime`>1661573100 AND `dateTime`<1661593200 THEN 5 ELSE NULL END AS gap_id,`dateTime`,`outTemp`,`outHumidity`,`rain`,`rainRate`,`windSpeed`,`windGust`,`barometer` FROM `pocasi-loucka.eu_GW1000`.`archive` WHERE (`dateTime`>1648403400 AND `dateTime`<1648475700) OR (`dateTime`>1655394000 AND `dateTime`<1655397900) OR (`dateTime`>1655568900 AND `dateTime`<1655572800) OR (`dateTime`>1656935100 AND `dateTime`<1656942900) OR (`dateTime`>1661573100 AND `dateTime`<1661593200)) q;
